import { randomUUID } from "node:crypto";

/** The owner is an application-level identity, not a queue scheduler. */
export type HotFileWriteOwnerId = string;

/**
 * Adapter for the existing per-file mutation queue/lease kernel (issue #167).
 * This module deliberately does not create a queue or schedule work itself.
 */
export interface FileMutationQueueAdapter {
  runExclusive<T>(filePath: string, task: () => T | Promise<T>): T | Promise<T>;
}

export interface HotFileWriteHolder {
  ownerId: HotFileWriteOwnerId;
  token: string;
}

export interface HotFileWriteClaimSuccess {
  ok: true;
  filePath: string;
  ownerId: HotFileWriteOwnerId;
  token: string;
  reentrant: boolean;
}

export interface HotFileWriteClaimConflict {
  ok: false;
  filePath: string;
  ownerId: HotFileWriteOwnerId;
  conflict: true;
  holder: HotFileWriteHolder;
}

export type HotFileWriteClaim =
  | HotFileWriteClaimSuccess
  | HotFileWriteClaimConflict;

export type HotFileWriteReleaseResult =
  | { ok: true; filePath: string; ownerId: HotFileWriteOwnerId; released: true }
  | {
      ok: false;
      filePath: string;
      ownerId: HotFileWriteOwnerId;
      released: false;
      reason: "token-mismatch" | "not-owner" | "not-claimed";
    };

interface OwnershipRecord extends HotFileWriteHolder {
  filePath: string;
}

function assertFilePath(filePath: string): void {
  if (typeof filePath !== "string" || filePath.length === 0) {
    throw new TypeError("filePath must be a non-empty string");
  }
}

function assertOwnerId(ownerId: HotFileWriteOwnerId): void {
  if (typeof ownerId !== "string" || ownerId.length === 0) {
    throw new TypeError("ownerId must be a non-empty string");
  }
}

/**
 * Process-local, CAS-like ownership registry.
 *
 * JavaScript's synchronous map update is the compare-and-set boundary: an owner is
 * installed or the currently installed holder is returned as a conflict. A
 * second owner never receives a write token.
 */
export class HotFileWriteOwnerRegistry {
  readonly #owners = new Map<string, OwnershipRecord>();

  claim(filePath: string, ownerId: HotFileWriteOwnerId): HotFileWriteClaim {
    assertFilePath(filePath);
    assertOwnerId(ownerId);

    const current = this.#owners.get(filePath);
    if (current) {
      if (current.ownerId === ownerId) {
        return {
          ok: true,
          filePath,
          ownerId,
          token: current.token,
          reentrant: true,
        };
      }
      return {
        ok: false,
        filePath,
        ownerId,
        conflict: true,
        holder: {
          ownerId: current.ownerId,
          token: current.token,
        },
      };
    }

    const record: OwnershipRecord = {
      filePath,
      ownerId,
      token: randomUUID(),
    };
    this.#owners.set(filePath, record);
    return {
      ok: true,
      filePath,
      ownerId,
      token: record.token,
      reentrant: false,
    };
  }

  release(
    filePath: string,
    ownerId: HotFileWriteOwnerId,
    token: string,
  ): HotFileWriteReleaseResult {
    assertFilePath(filePath);
    assertOwnerId(ownerId);
    if (typeof token !== "string" || token.length === 0) {
      throw new TypeError("token must be a non-empty string");
    }

    const current = this.#owners.get(filePath);
    if (!current) {
      return {
        ok: false,
        filePath,
        ownerId,
        released: false,
        reason: "not-claimed",
      };
    }
    if (current.ownerId !== ownerId) {
      return {
        ok: false,
        filePath,
        ownerId,
        released: false,
        reason: "not-owner",
      };
    }
    if (current.token !== token) {
      return {
        ok: false,
        filePath,
        ownerId,
        released: false,
        reason: "token-mismatch",
      };
    }

    this.#owners.delete(filePath);
    return {
      ok: true,
      filePath,
      ownerId,
      released: true,
    };
  }

  holder(filePath: string): HotFileWriteHolder | undefined {
    assertFilePath(filePath);
    const current = this.#owners.get(filePath);
    if (!current) return undefined;
    return {
      ownerId: current.ownerId,
      token: current.token,
    };
  }

  isOwner(filePath: string, ownerId: HotFileWriteOwnerId, token: string): boolean {
    const current = this.#owners.get(filePath);
    return Boolean(
      current &&
        current.ownerId === ownerId &&
        current.token === token,
    );
  }
}

/** Shared registry used by the runtime helpers. */
export const hotFileWriteOwners = new HotFileWriteOwnerRegistry();

export function claimHotFileWriteOwner(
  filePath: string,
  ownerId: HotFileWriteOwnerId,
  registry: HotFileWriteOwnerRegistry = hotFileWriteOwners,
): HotFileWriteClaim {
  return registry.claim(filePath, ownerId);
}

export function releaseHotFileWriteOwner(
  filePath: string,
  ownerId: HotFileWriteOwnerId,
  token: string,
  registry: HotFileWriteOwnerRegistry = hotFileWriteOwners,
): HotFileWriteReleaseResult {
  return registry.release(filePath, ownerId, token);
}

export class HotFileWriteConflictError extends Error {
  readonly filePath: string;
  readonly requestedOwnerId: HotFileWriteOwnerId;
  readonly holder: HotFileWriteHolder;

  constructor(
    filePath: string,
    requestedOwnerId: HotFileWriteOwnerId,
    holder: HotFileWriteHolder,
  ) {
    super(
      `Hot-file write conflict for ${filePath}: owner ${requestedOwnerId} is held by ${holder.ownerId}`,
    );
    this.name = "HotFileWriteConflictError";
    this.filePath = filePath;
    this.requestedOwnerId = requestedOwnerId;
    this.holder = holder;
  }
}

export interface HotFileWriteOperationOptions {
  registry?: HotFileWriteOwnerRegistry;
}

/**
 * Claim ownership, then execute the mutation through the existing file mutation
 * queue adapter. The adapter owns serialization; this helper owns only the
 * write-attribution invariant. A failed mutation always rolls the claim back.
 */
export async function withHotFileWriteOwner<T>(
  filePath: string,
  ownerId: HotFileWriteOwnerId,
  queue: FileMutationQueueAdapter,
  operation: () => T | Promise<T>,
  options: HotFileWriteOperationOptions = {},
): Promise<T> {
  if (!queue || typeof queue.runExclusive !== "function") {
    throw new TypeError("queue must provide runExclusive(filePath, task)");
  }
  if (typeof operation !== "function") {
    throw new TypeError("operation must be a function");
  }

  const registry = options.registry ?? hotFileWriteOwners;
  const claim = registry.claim(filePath, ownerId);
  if (!claim.ok) {
    throw new HotFileWriteConflictError(filePath, ownerId, claim.holder);
  }

  try {
    return await queue.runExclusive(filePath, operation);
  } finally {
    registry.release(filePath, ownerId, claim.token);
  }
}

/** Compatibility aliases for callers that use shorter names. */
export const claimWriteOwner = claimHotFileWriteOwner;
export const releaseWriteOwner = releaseHotFileWriteOwner;
export const runWithWriteOwner = withHotFileWriteOwner;

# L06 closure: hot-file write ownership

## Design

L06 layers a small ownership registry over the existing per-file mutation queue from issue #167. The registry answers a single question: which owner currently has verifiable write attribution for a path?

Ownership installation is a synchronous compare-and-set operation over a path-keyed map. The first owner receives an unguessable token. Re-claiming by that owner is idempotent and returns the existing token. A different owner receives an explicit conflict and the current holder; no contender token is issued.

The mutation itself is always delegated to `FileMutationQueueAdapter.runExclusive`. That adapter is the boundary for the existing FIFO, capacity, timeout, lease, and non-interleaving guarantees. L06 adds no scheduler, worker, timer, or parallel queue.

## Lifecycle and recovery

A successful claim is released only by the matching owner and token. Invalid releases leave the record intact. After a valid release, another owner can claim the path. `withHotFileWriteOwner` releases the claim in `finally`, so an exception or rejected promise rolls ownership back and permits recovery.

## Example

```ts
const claim = claimHotFileWriteOwner("reports/daily.md", "job-42");
if (!claim.ok) {
  // Explicit conflict. The holder is available for diagnostics.
  throw new Error(`write owner conflict: ${claim.holder.ownerId}`);
}

try {
  await existingFileMutationQueue.runExclusive(
    "reports/daily.md",
    () => writeDailyReport(),
  );
} finally {
  releaseHotFileWriteOwner(
    "reports/daily.md",
    "job-42",
    claim.token,
  );
}
```

For new callers, `withHotFileWriteOwner` combines the claim, queue delegation, and rollback:

```ts
await withHotFileWriteOwner(
  "reports/daily.md",
  "job-42",
  existingFileMutationQueue,
  () => writeDailyReport(),
);
```

## Verification

The targeted harness covers first claim, same-owner re-entry, cross-owner conflict, token-mismatched release, release/reclaim recovery, queue start/end ordering, and exception rollback. Repository checks remain the source of truth for runtime-core types, scoped lint, harness validate/dry-run, comms replay/compare, credential scanning, and SHA256SUMS readback.

